export interface Activity {
  id: string;
  name: string;
  description?: string;
  category: string;
  dailyTarget?: number;
  createdAt: number;
}

export interface CompletionRecord {
  date: string; // ISO date YYYY-MM-DD
  completions: Record<string, boolean>; // { activityId: boolean }
}

export interface AppData {
  version: number;
  activities: Activity[];
  completions: CompletionRecord[];
}

export type Tab = 'aktivitäten' | 'dashboard';

export const STORAGE_KEY = 'pulseboard:data:v1';
export const CURRENT_VERSION = 1;
export const CATEGORIES = [
  'Arbeit',
  'Gesundheit',
  'Freizeit',
  'Bildung',
  'Persönlich',
];

import { STORAGE_KEY, CURRENT_VERSION, CATEGORIES } from '../constants';
import type { AppData, CompletionRecord, Activity } from '../types';

let pendingWrite: Promise<void> | null = null;

function deserialize(raw: string | null): AppData | null {
  if (raw === null) return null;
  try {
    const data = JSON.parse(raw) as AppData;
    if (typeof data !== 'object' || data === null) return null;
    if (typeof data.version !== 'number' || data.version < 1) return null;
    if (!Array.isArray(data.activities)) return null;
    if (!Array.isArray(data.completions)) return null;
    // Validate activities
    for (const a of data.activities) {
      if (typeof a.id !== 'string') return null;
      if (typeof a.name !== 'string' || a.name.length === 0) return null;
    }
    // Validate completions
    for (const c of data.completions) {
      if (typeof c.date !== 'string') return null;
      if (typeof c.completions !== 'object' || c.completions === null) return null;
    }
    return data;
  } catch {
    return null;
  }
}

export function load(): AppData {
  const raw = localStorage.getItem(STORAGE_KEY);
  const parsed = deserialize(raw);
  if (parsed !== null) return parsed;
  // Return fresh default on failure/corruption
  console.warn('PulseBoard: konnte Daten nicht laden, starte mit leerer Datei.');
  return freshData();
}

export function save(data: AppData): void {
  if (pendingWrite) return; // prevent race writes
  pendingWrite = Promise.resolve().then(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    pendingWrite = null;
  });
}

export function getAllCategories(data: AppData): string[] {
  const categories = new Set<string>();
  for (const activity of data.activities) {
    if (activity.category.trim()) categories.add(activity.category.trim());
  }
  const fallback = CATEGORIES.filter((c) => !data.activities.some((a) => a.category === c));
  return [...categories, ...fallback];
}

export function getToday(): string {
  const now = new Date();
  const offset = now.getTimezoneOffset();
  const utc = new Date(now.getTime() + offset * 60000);
  return utc.toISOString().slice(0, 10);
}

export function getYesterday(date: string): string {
  return shiftDate(date, -1);
}

export function getTomorrow(date: string): string {
  return shiftDate(date, 1);
}

function shiftDate(date: string, days: number): string {
  const [year, month, day] = date.split('-').map(Number);
  const d = new Date(year, month - 1, day + days);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${dd}`;
}

export function formatGermanDate(iso: string): string {
  const [year, month, day] = iso.split('-').map(Number);
  const d = new Date(year, month - 1, day);
  const options: Intl.DateTimeFormatOptions = {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
    weekday: 'short',
  };
  return d.toLocaleDateString('de-DE', options);
}

export function freshData(): AppData {
  return {
    version: CURRENT_VERSION,
    activities: [],
    completions: [],
  };
}

export function markComplete(data: AppData, date: string, activityId: string, completed: boolean): AppData {
  const completions = data.completions.map((c) => {
    if (c.date === date) {
      return { ...c, completions: { ...c.completions, [activityId]: completed } };
    }
    return c;
  });
  return { ...data, completions };
}

export function addActivity(data: AppData, activity: Activity): AppData {
  return { ...data, activities: [...data.activities, activity] };
}

export function updateActivity(data: AppData, activityId: string, updates: Partial<Activity>): AppData {
  return {
    ...data,
    activities: data.activities.map((a) =>
      a.id === activityId ? { ...a, ...updates } : a
    ),
  };
}

export function removeActivity(data: AppData, activityId: string): AppData {
  return {
    ...data,
    activities: data.activities.filter((a) => a.id !== activityId),
    completions: data.completions.map((c) => {
      const newCompletions = { ...c.completions };
      delete newCompletions[activityId];
      return { ...c, completions: newCompletions };
    }).filter((c) => Object.keys(c.completions).length > 0),
  };
}

export function getCompletionsForDate(data: AppData, date: string): CompletionRecord | undefined {
  return data.completions.find((c) => c.date === date);
}

export function getIsComplete(data: AppData, date: string, activityId: string): boolean {
  const record = data.completions.find((c) => c.date === date);
  return record?.completions[activityId] === true;
}

export function isFutureDate(date: string): boolean {
  return date > getToday();
}

export function isToday(date: string): boolean {
  return date === getToday();
}

import { useState } from 'react';

export function useLocalStorage<T>(key: string, initialValue: T): [T, (value: T) => void] {
  const [state, setState] = useState<T>(() => {
    try {
      const stored = localStorage.getItem(key);
      if (stored === null) return initialValue;
      return JSON.parse(stored) as T;
    } catch {
      return initialValue;
    }
  });

  const setValue = (value: T) => {
    setState(value);
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch {
      // ignore quota errors
    }
  };

  return [state, setValue];
}

import { useMemo, useState } from 'react';
import { getCompletionsForDate, getIsComplete, getToday, markComplete } from '../lib/storage';
import { isFutureDate } from '../lib/storage';
import { getYesterday, getTomorrow, getAllCategories } from '../lib/storage';
import type { AppData, CompletionRecord, Tab } from '../types';

interface UseDayDataReturn {
  tab: Tab;
  setTab: (tab: Tab) => void;
  selectedDate: string;
  setSelectedDate: (date: string) => void;
  completionRecord: CompletionRecord | undefined;
  isToday: boolean;
  isFuture: boolean;
  yesterday: string;
  tomorrow: string;
  categories: string[];
  selectedCategory: string | null;
  setSelectedCategory: (cat: string | null) => void;
  toggleComplete: (activityId: string, completed: boolean) => void;
  activities: { activity: AppData['activities'][number]; isComplete: boolean }[];
  stats: {
    completed: number;
    open: number;
    percentage: number;
  };
}

export function useDayData(data: AppData): UseDayDataReturn {
  const [tab, setTab] = useState<Tab>('aktivitäten');
  const [selectedDate, setSelectedDate] = useState<string>(getToday());
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  const today = getToday();
  const yesterday = getYesterday(selectedDate);
  const tomorrow = getTomorrow(selectedDate);
  const isToday = selectedDate === today;
  const isFuture = isFutureDate(selectedDate);

  const completionRecord = useMemo(
    () => getCompletionsForDate(data, selectedDate),
    [data, selectedDate]
  );

  const categories = useMemo(() => getAllCategories(data), [data]);

  const activities = useMemo(() => {
    return data.activities
      .filter((a) => !selectedCategory || a.category === selectedCategory)
      .map((activity) => ({
        activity,
        isComplete: getIsComplete(data, selectedDate, activity.id),
      }));
  }, [data, selectedDate, selectedCategory]);

  const stats = useMemo(() => {
    const completed = activities.filter((a) => a.isComplete).length;
    const total = activities.length;
    const open = total - completed;
    const percentage = total > 0 ? Math.round((completed / total) * 100) : 0;
    return { completed, open, percentage };
  }, [activities]);

  const toggleComplete = (activityId: string, completed: boolean) => {
    setSelectedDate(selectedDate);
  };

  return {
    tab,
    setTab,
    selectedDate,
    setSelectedDate,
    completionRecord,
    isToday,
    isFuture,
    yesterday,
    tomorrow,
    categories,
    selectedCategory,
    setSelectedCategory,
    toggleComplete,
    activities,
    stats,
  };
}

import { useMemo, useState } from 'react';
import {
  getCompletionsForDate,
  getIsComplete,
  getToday,
  getYesterday,
  getTomorrow,
  getAllCategories,
