import type { AppData } from '../types';

interface Props {
  activities: { activity: AppData['activities'][number]; isComplete: boolean }[];
  isFuture: boolean;
  isToday: boolean;
  onToggleComplete: (activityId: string, completed: boolean) => void;
}

export function ActivitiesPanel({
  activities,
  isFuture,
  isToday,
  onToggleComplete,
}: Props) {
  if (activities.length === 0) {
    if (isFuture) {
      return (
        <div className="empty-state">
          <p>Dieser Tag liegt in der Zukunft.</p>
          <p>Hier ist noch nichts zu planen.</p>
        </div>
      );
    }
    return (
      <div className="empty-state">
        <p>Es ist ein ruhiger Tag.</p>
        <p>Füge deine erste Aktivität über den "+"-Button unten hinzu.</p>
      </div>
    );
  }

  return (
    <ul className="activity-list" role="list">
      {activities.map(({ activity, isComplete }) => (
        <li
          key={activity.id}
          className={`activity-item${isComplete ? ' done' : ''}${
            !isToday && !isFuture ? ' past' : ''
          }`}
        >
          <label className="activity-label">
            <input
              type="checkbox"
              checked={isComplete}
              disabled={isFuture}
              onChange={(e) => onToggleComplete(activity.id, e.target.checked)}
              aria-label={`${isComplete ? 'Abhaken' : 'Markieren als erledigt'}: ${activity.name}`}
            />
            <span className="activity-text">
              <span className="activity-name">{activity.name}</span>
              {activity.description && (
                <span className="activity-description">{activity.description}</span>
              )}
              {activity.dailyTarget && (
                <span className="activity-target">
                  Ziel: {activity.dailyTarget}
                </span>
              )}
            </span>
            <button
              className="activity-delete"
              onClick={() =>
                window.confirm(
                  `"${activity.name}" wirklich löschen?`
                ) && onToggleComplete(activity.id, false)
              }
              aria-label={`"${activity.name}" löschen`}
              tabIndex={-1}
            >
              ×
            </button>
          </label>
        </li>
      ))}
    </ul>
  );
}

import { useState } from 'react';
import { generateId } from '../lib/generateId';
import type { Activity } from '../types';

interface Props {
  categories: string[];
  existingNames: string[];
  onSubmit: (activity: Activity) => void;
  onClose: () => void;
}

export function ActivityForm({ categories, existingNames, onSubmit, onClose }: Props) {
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [category, setCategory] = useState(categories[0] ?? '');
  const [dailyTarget, setDailyTarget] = useState('');
  const [error, setError] = useState('');

  const handleNameInput = (value: string) => {
    setName(value);
    if (value.length > 0 && existingNames.includes(value.trim().toLowerCase())) {
      setError('Ein Eintrag mit diesem Namen existiert bereits.');
    } else {
      setError('');
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = name.trim();
    if (trimmed.length === 0) {
      setError('Name darf nicht leer sein.');
      return;
    }
    if (existingNames.includes(trimmed.toLowerCase())) {
      setError('Ein Eintrag mit diesem Namen existiert bereits.');
      return;
    }
    onSubmit({
      id: generateId(),
      name: trimmed,
      description: description.trim() || undefined,
      category,
      dailyTarget: dailyTarget.trim() ? Number(dailyTarget) : undefined,
      createdAt: Date.now(),
    });
    onClose();
  };

  return (
    <form className="activity-form" onSubmit={handleSubmit}>
      <h2>Aktivität hinzufügen</h2>
      <div className="form-group">
        <label htmlFor="act-name">Name *</label>
        <input
          id="act-name"
          type="text"
          value={name}
          onChange={(e) => handleNameInput(e.target.value)}
          autoFocus
          required
          maxLength={100}
        />
      </div>
      <div className="form-group">
        <label htmlFor="act-desc">Beschreibung</label>
        <textarea
          id="act-desc"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          maxLength={300}
          rows={2}
        />
      </div>
      <div className="form-group">
        <label htmlFor="act-cat">Kategorie</label>
        <select
          id="act-cat"
          value={category}
          onChange={(e) => setCategory(e.target.value)}
        >
          {categories.map((c) => (
            <option key={c} value={c}>{c}</option>
          ))}
        </select>
      </div>
      <div className="form-group">
        <label htmlFor="act-target">Tagesziel</label>
        <input
          id="act-target"
          type="number"
          min={1}
          value={dailyTarget}
          onChange={(e) => setDailyTarget(e.target.value)}
          placeholder="z. B. 8"
        />
      </div>
      {error && <p className="form-error">{error}</p>}
      <div className="form-actions">
        <button type="button" className="btn btn-secondary" onClick={onClose}>
          Abbrechen
        </button>
        <button type="submit" className="btn btn-primary" disabled={error !== ''}>
          Speichern
        </button>
      </div>
    </form>
  );
}

import type { AppData } from '../types';
import { getCompletionsForDate, getToday, getAllCategories } from '../lib/storage';

interface Props {
  data: AppData;
  selectedDate: string;
}

export function Dashboard({ data, selectedDate }: Props) {
  const today = getToday();
  const isToday = selectedDate === today;

  const completionRecord = getCompletionsForDate(data, selectedDate);
  const activities = isToday ? data.activities : data.activities;
  const allCompleted =
    activities.length > 0
      ? activities.every((a) =>
          getCompletionsForDate(data, selectedDate)?.completions[a.id] === true
        )
      : false;
  const stats = computeStats(activities, selectedDate);
  const categoryStats = computeCategoryStats(data, selectedDate);

  return (
    <div className="dashboard">
      <section className="stat-row">
        <div className="stat-card">
          <span className="stat-number">{stats.completed}</span>
          <span className="stat-label">Erledigt</span>
        </div>
        <div className="stat-card">
          <span className="stat-number">{stats.open}</span>
          <span className="stat-label">Offen</span>
        </div>
        <div className="stat-card">
          <span className="stat-number">{stats.percentage}</span>
          <span className="stat-label">Prozent</span>
        </div>
      </section>

      <section className="category-stats">
        <h3>Nach Kategorie</h3>
        {categoryStats.length === 0 ? (
          <p className="empty-text">Noch keine Aktivitäten.</p>
        ) : (
          <ul className="cat-list">
            {categoryStats.map(({ name, total, done }) => (
              <li key={name} className="cat-item">
                <span className="cat-name">{name}</span>
                <span className="cat-bar-wrap">
                  <span
                    className="cat-bar"
                    style={{ width: `${total > 0 ? (done / total) * 100 : 0}%` }}
                  />
                </span>
                <span className="cat-count">
                  {done}/{total}
                </span>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

function computeStats(activities: AppData['activities'], date: string) {
  const completed = activities.filter((a) =>
    getCompletionsForDate({ version: 1, activities: [], completions: [{ date, completions: { [a.id]: true } }] }, date)
  ).length;
  return { completed, open: activities.length - completed, percentage: 0 };
}

function computeCategoryStats(
  data: AppData,
  date: string
): { name: string; total: number; done: number }[] {
  const result: Record<string, { total: number; done: number }> = {};
  for (const a of data.activities) {
    if (!result[a.category]) {
      result[a.category] = { total: 0, done: 0 };
    }
    result[a.category].total++;
    if (getCompletionsForDate(data, date)?.completions[a.id]) {
      result[a.category].done++;
    }
  }
  return Object.entries(result).map(([name, { total, done }]) => ({
    name,
    total,
    done,
  }));
}

import { getToday, getYesterday, getTomorrow } from '../lib/storage';

interface Props {
  selectedDate: string;
  yesterday: string;
  tomorrow: string;
  onNavigate: (date: string) => void;
  onToday: () => void;
  onPrev: () => void;
  onNext: () => void;
}

export function DayNavigator({
  selectedDate,
  yesterday,
  tomorrow,
  onNavigate,
  onToday,
  onPrev,
  onNext,
}: Props) {
  return (
    <nav className="day-nav" aria-label="Tagesauswahl">
      <button
        className="day-nav-btn"
        onClick={() => onNavigate(yesterday)}
        aria-label="Voriger Tag"
      >
        ‹
      </button>
      <button
        className="day-nav-btn day-nav-today"
        onClick={onToday}
        aria-label="Heute"
      >
        Heute
      </button>
      <div className="day-nav-date">{selectedDate}</div>
      <button
        className="day-nav-btn"
        onClick={() => onNavigate(tomorrow)}
        aria-label="Nächster Tag"
      >
        ›
      </button>
    </nav>
  );
}

interface Props {
  categories: string[];
  selectedCategory: string | null;
  onFilter: (cat: string | null) => void;
}

export function CategoryFilter({ categories, selectedCategory, onFilter }: Props) {
  if (categories.length === 0) return null;

  return (
    <nav className="category-nav" aria-label="Kategorie-Filter">
      <button
        className={`cat-filter-btn${selectedCategory === null ? ' active' : ''}`}
        onClick={() => onFilter(null)}
      >
        Alle
      </button>
      {categories.map((cat) => (
        <button
          key={cat}
          className={`cat-filter-btn${selectedCategory === cat ? ' active' : ''}`}
          onClick={() => onFilter(cat)}
        >
          {cat}
        </button>
      ))}
    </nav>
  );
}

const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';

export function generateId(): string {
  const time = Date.now().toString(36);
  const random = Math.random().toString(36).slice(2, 8);
  return `${time}${random}`;
}

import type { AppData } from '../types';

interface Props {
  activities: { activity: AppData['activities'][number]; isComplete: boolean }[];
  categoryStats: { name: string; total: number; done: number }[];
}

export function Dashboard({ activities, categoryStats }: Props) {
  const completed = activities.filter((a) => a.isComplete).length;
  const open = activities.length - completed;
  const percentage = activities.length > 0 ? Math.round((completed / activities.length) * 100) : 0;

  return (
    <div className="dashboard">
      <section className="stat-row">
        <div className="stat-card">
          <span className="stat-number">{completed}</span>
          <span className="stat-label">Erledigt</span>
        </div>
        <div className="stat-card">
          <span className="stat-number">{open}</span>
          <span className="stat-label">Offen</span>
        </div>
        <div className="stat-card">
          <span className="stat-number">{percentage}</span>
          <span className="stat-label">Prozent</span>
        </div>
      </section>

      <section className="category-stats">
        <h3>Nach Kategorie</h3>
        {categoryStats.length === 0 ? (
          <p className="empty-text">Noch keine Aktivitäten.</p>
        ) : (
          <ul className="cat-list">
            {categoryStats.map(({ name, total, done }) => (
              <li key={name} className="cat-item">
                <span className="cat-name">{name}</span>
                <span className="cat-bar-wrap">
                  <span
                    className="cat-bar"
