import { useMemo, useState } from 'react';
import {
  getCompletionsForDate,
  getIsComplete,
  getToday,
  getYesterday,
  getTomorrow,
  getAllCategories,
  isFutureDate,
  markComplete,
} from '../lib/storage';
import type { AppData, CompletionRecord, Tab } from '../types';

interface CategoryStat {
  name: string;
  total: number;
  done: number;
}

interface UseDayDataReturn {
  tab: Tab;
  setTab: (tab: Tab) => void;
  selectedDate: string;
  setSelectedDate: (date: string) => void;
  completionRecord: CompletionRecord | undefined;
  isToday: boolean;
  isFuture: boolean;
  yesterday: string;
  tomorrow: string;
  categories: string[];
  selectedCategory: string | null;
  setSelectedCategory: (cat: string | null) => void;
  activities: { activity: AppData['activities'][number]; isComplete: boolean }[];
  categoryStats: CategoryStat[];
  stats: {
    completed: number;
    open: number;
    percentage: number;
  };
  toggleComplete: (activityId: string, completed: boolean) => AppData;
  deleteActivity: (activityId: string) => AppData;
}

export function useDayData(data: AppData): UseDayDataReturn {
  const [tab, setTab] = useState<Tab>('aktivitäten');
  const [selectedDate, setSelectedDate] = useState<string>(getToday());
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  const today = getToday();
  const yesterday = getYesterday(selectedDate);
  const tomorrow = getTomorrow(selectedDate);
  const isTodayFlag = selectedDate === today;
  const isFuture = isFutureDate(selectedDate);

  const completionRecord = useMemo(
    () => getCompletionsForDate(data, selectedDate),
    [data, selectedDate]
  );

  const categories = useMemo(() => getAllCategories(data), [data]);

  const activities = useMemo(() => {
    return data.activities
      .filter((a) => !selectedCategory || a.category === selectedCategory)
      .map((activity) => ({
        activity,
        isComplete: getIsComplete(data, selectedDate, activity.id),
      }));
  }, [data, selectedDate, selectedCategory]);

  const categoryStats = useMemo(() => {
    const result: Record<string, { total: number; done: number }> = {};
    for (const a of data.activities) {
      if (!result[a.category]) {
        result[a.category] = { total: 0, done: 0 };
      }
      result[a.category].total++;
      if (getIsComplete(data, selectedDate, a.id)) {
        result[a.category].done++;
      }
    }
    return Object.entries(result).map(([name, { total, done }]) => ({
      name,
      total,
      done,
    }));
  }, [data, selectedDate]);

  const stats = useMemo(() => {
    const completed = activities.filter((a) => a.isComplete).length;
    const total = activities.length;
    const open = total - completed;
    const percentage = total > 0 ? Math.round((completed / total) * 100) : 0;
    return { completed, open, percentage };
  }, [activities]);

  const toggleComplete = (activityId: string, completed: boolean): AppData => {
    return markComplete(data, selectedDate, activityId, completed);
  };

  const deleteActivity = (activityId: string): AppData => {
    return {
      ...data,
      activities: data.activities.filter((a) => a.id !== activityId),
      completions: data.completions.map((c) => {
        const newCompletions = { ...c.completions };
        delete newCompletions[activityId];
        return { ...c, completions: newCompletions };
      }).filter((c) => Object.keys(c.completions).length > 0),
    };
  };

  return {
    tab,
    setTab,
    selectedDate,
    setSelectedDate,
    completionRecord,
    isToday: isTodayFlag,
    isFuture,
    yesterday,
    tomorrow,
    categories,
    selectedCategory,
    setSelectedCategory,
    activities,
    categoryStats,
    stats,
    toggleComplete,
    deleteActivity,
  };
}

import type { AppData } from '../types';

interface Props {
  activities: { activity: AppData['activities'][number]; isComplete: boolean }[];
  isFuture: boolean;
  isToday: boolean;
  onToggleComplete: (activityId: string, completed: boolean) => void;
  onDelete: (activityId: string) => void;
}

export function ActivitiesPanel({
  activities,
  isFuture,
  isToday,
  onToggleComplete,
  onDelete,
}: Props) {
  if (activities.length === 0) {
    if (isFuture) {
      return (
        <div className="empty-state">
          <p>Dieser Tag liegt in der Zukunft.</p>
          <p>Hier ist noch nichts zu planen.</p>
        </div>
      );
    }
    return (
      <div className="empty-state">
        <p>Es ist ein ruhiger Tag.</p>
        <p>Füge deine erste Aktivität über den "+"-Button unten hinzu.</p>
      </div>
    );
  }

  return (
    <ul className="activity-list" role="list">
      {activities.map(({ activity, isComplete }) => (
        <li
          key={activity.id}
          className={`activity-item${isComplete ? ' done' : ''}${
            !isToday && !isFuture ? ' past' : ''
          }`}
        >
          <label className="activity-label">
            <input
              type="checkbox"
              checked={isComplete}
              disabled={isFuture}
              onChange={(e) => onToggleComplete(activity.id, e.target.checked)}
              aria-label={`${isComplete ? 'Abhaken' : 'Markieren als erledigt'}: ${activity.name}`}
            />
            <span className="activity-text">
              <span className="activity-name">{activity.name}</span>
              {activity.description && (
                <span className="activity-description">{activity.description}</span>
              )}
              {activity.dailyTarget && (
                <span className="activity-target">
                  Ziel: {activity.dailyTarget}
                </span>
              )}
            </span>
            <button
              className="activity-delete"
              onClick={() => {
                onDelete(activity.id);
              }}
              aria-label={`"${activity.name}" löschen`}
              tabIndex={-1}
            >
              ×
            </button>
          </label>
        </li>
      ))}
    </ul>
  );
}

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';
import './index.css';

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>
);

import { useState } from 'react';
import { load, save } from './lib/storage';
import { useDayData } from './hooks/useDayData';
import { useLocalStorage } from './hooks/useLocalStorage';
import { Dashboard } from './components/Dashboard';
import { ActivitiesPanel } from './components/ActivitiesPanel';
import { ActivityForm } from './components/ActivityForm';
import { CategoryFilter } from './components/CategoryFilter';
import { DayNavigator } from './components/DayNavigator';
import { formatGermanDate, getToday } from './lib/storage';
import type { Tab } from './types';

function App(): JSX.Element {
  const [tabData, setTabData] = useLocalStorage<ReturnType<typeof useDayData>>(
    'pulseboard:tab-state',
    {
      tab: 'aktivitäten',
      setTab: () => {},
      selectedDate: getToday(),
      setSelectedDate: () => {},
      completionRecord: undefined,
      isToday: true,
      isFuture: false,
      yesterday: '',
      tomorrow: '',
      categories: [],
      selectedCategory: null,
      setSelectedCategory: () => {},
      activities: [],
      categoryStats: [],
      stats: { completed: 0, open: 0, percentage: 0 },
      toggleComplete: () => ({
        version: 1,
        activities: [],
        completions: [],
      }),
      deleteActivity: () => ({
        version: 1,
        activities: [],
        completions: [],
      }),
    }
  );

  const [appData, setAppData] = useState(load);

  const dayData = useDayData(appData);

  const [formOpen, setFormOpen] = useState(false);

  // Sync tabData with dayData — we need to keep reactive state
  const tab = dayData.tab;
  const selectedDate = dayData.selectedDate;

  const handleDateChange = (date: string) => {
    dayData.setSelectedDate(date);
  };

  const handleCategoryFilter = (cat: string | null) => {
    dayData.setSelectedCategory(cat);
  };

  const handleToggleComplete = (activityId: string, completed: boolean) => {
    const newData = dayData.toggleComplete(activityId, completed);
    setAppData(newData);
    save(newData);
  };

  const handleDeleteActivity = (activityId: string) => {
    if (!window.confirm('Aktivität wirklich löschen?')) return;
    const newData = dayData.deleteActivity(activityId);
    setAppData(newData);
    save(newData);
  };

  const handleAddActivity = (activity: {
    id: string;
    name: string;
    description?: string;
    category: string;
    dailyTarget?: number;
    createdAt: number;
  }) => {
    const newData = {
      ...appData,
      activities: [...appData.activities, activity],
    };
    setAppData(newData);
    save(newData);
  };

  const today = getToday();

  return (
    <div className="app">
      <header className="app-header">
        <div className="app-title">
          <span className="title-bar" />
          <h1>PulseBoard</h1>
        </div>
        <div className="app-tabs">
          <button
            className={`tab-btn${tab === 'aktivitäten' ? ' active' : ''}`}
            onClick={() => dayData.setTab('aktivitäten')}
          >
            Aktivitäten
          </button>
          <button
            className={`tab-btn${tab === 'dashboard' ? ' active' : ''}`}
            onClick={() => dayData.setTab('dashboard')}
          >
            Dashboard
          </button>
        </div>
      </header>

      <main className="app-main">
        {tab === 'aktivitäten' ? (
          <>
            <DayNavigator
              selectedDate={selectedDate}
              yesterday={dayData.yesterday}
              tomorrow={dayData.tomorrow}
              onNavigate={handleDateChange}
              onToday={() => handleDateChange(today)}
              onPrev={() => handleDateChange(dayData.yesterday)}
              onNext={() => handleDateChange(dayData.tomorrow)}
            />

            <div className="progress-bar-wrap">
              <div className="progress-bar" style={{ width: `${dayData.stats.percentage}%` }} />
            </div>

            <div className="stats-inline">
              <span>{dayData.stats.completed} von {dayData.activities.length}</span>
              <span>{dayData.stats.percentage}%</span>
            </div>

            <CategoryFilter
              categories={dayData.categories}
              selectedCategory={dayData.selectedCategory}
              onFilter={handleCategoryFilter}
            />

            <ActivitiesPanel
              activities={dayData.activities}
              isFuture={dayData.isFuture}
              isToday={dayData.isToday}
              onToggleComplete={handleToggleComplete}
              onDelete={handleDeleteActivity}
            />

            <button
              className="fab"
              onClick={() => setFormOpen(true)}
              aria-label="Aktivität hinzufügen"
            >
              +
            </button>
          </>
        ) : (
          <Dashboard
            activities={dayData.activities}
            categoryStats={dayData.categoryStats}
          />
        )}
      </main>

      {formOpen && (
        <div className="modal-overlay" onClick={() => setFormOpen(false)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <ActivityForm
              categories={dayData.categories}
              existingNames={appData.activities.map((a) => a.name.toLowerCase())}
              onSubmit={handleAddActivity}
              onClose={() => setFormOpen(false)}
            />
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

