import { useMemo } from 'react';
import {
  getCompletionsForDate,
  getIsComplete,
  getToday,
  getYesterday,
  getTomorrow,
  getAllCategories,
  isFutureDate,
  markComplete,
} from '../lib/storage';
import type { AppData, CompletionRecord, Tab } from '../types';

interface UseDayDataOptions {
  selectedDate: string;
  selectedCategory: string | null;
  tab: Tab;
  onDateChange: (date: string) => void;
  onCategoryChange: (cat: string | null) => void;
  onTabChange: (tab: Tab) => void;
}

interface CategoryStat {
  name: string;
  total: number;
  done: number;
}

interface UseDayDataReturn {
  tab: Tab;
  setTab: (tab: Tab) => void;
  selectedDate: string;
  setSelectedDate: (date: string) => void;
  completionRecord: CompletionRecord | undefined;
  isToday: boolean;
  isFuture: boolean;
  yesterday: string;
  tomorrow: string;
  categories: string[];
  selectedCategory: string | null;
  setSelectedCategory: (cat: string | null) => void;
  activities: { activity: AppData['activities'][number]; isComplete: boolean }[];
  categoryStats: CategoryStat[];
  stats: {
    completed: number;
    open: number;
    percentage: number;
  };
  toggleComplete: (activityId: string, completed: boolean) => AppData;
  deleteActivity: (activityId: string) => AppData;
}

export function useDayData(data: AppData, options: UseDayDataOptions): UseDayDataReturn {
  const { selectedDate, selectedCategory, tab } = options;

  const today = getToday();
  const yesterday = getYesterday(selectedDate);
  const tomorrow = getTomorrow(selectedDate);
  const isTodayFlag = selectedDate === today;
  const isFuture = isFutureDate(selectedDate);

  const completionRecord = useMemo(
    () => getCompletionsForDate(data, selectedDate),
    [data, selectedDate]
  );

  const categories = useMemo(() => getAllCategories(data), [data]);

  const activities = useMemo(() => {
    return data.activities
      .filter((a) => !selectedCategory || a.category === selectedCategory)
      .map((activity) => ({
        activity,
        isComplete: getIsComplete(data, selectedDate, activity.id),
      }));
  }, [data, selectedDate, selectedCategory]);

  const categoryStats = useMemo(() => {
    const result: Record<string, { total: number; done: number }> = {};
    for (const a of data.activities) {
      if (!result[a.category]) {
        result[a.category] = { total: 0, done: 0 };
      }
      result[a.category].total++;
      if (getIsComplete(data, selectedDate, a.id)) {
        result[a.category].done++;
      }
    }
    return Object.entries(result).map(([name, { total, done }]) => ({
      name,
      total,
      done,
    }));
  }, [data, selectedDate]);

  const stats = useMemo(() => {
    const completed = activities.filter((a) => a.isComplete).length;
    const total = activities.length;
    const open = total - completed;
    const percentage = total > 0 ? Math.round((completed / total) * 100) : 0;
    return { completed, open, percentage };
  }, [activities]);

  const toggleComplete = (activityId: string, completed: boolean): AppData => {
    return markComplete(data, selectedDate, activityId, completed);
  };

  const deleteActivity = (activityId: string): AppData => {
    return {
      ...data,
      activities: data.activities.filter((a) => a.id !== activityId),
      completions: data.completions.map((c) => {
        const newCompletions = { ...c.completions };
        delete newCompletions[activityId];
        return { ...c, completions: newCompletions };
      }).filter((c) => Object.keys(c.completions).length > 0),
    };
  };

  return {
    tab,
    setTab: options.onTabChange,
    selectedDate,
    setSelectedDate: options.onDateChange,
    completionRecord,
    isToday: isTodayFlag,
    isFuture,
    yesterday,
    tomorrow,
    categories,
    selectedCategory,
    setSelectedCategory: options.onCategoryChange,
    activities,
    categoryStats,
    stats,
    toggleComplete,
    deleteActivity,
  };
}

import { useState } from 'react';
import { load, save, getToday } from './lib/storage';
import { useDayData } from './hooks/useDayData';
import { Dashboard } from './components/Dashboard';
import { ActivitiesPanel } from './components/ActivitiesPanel';
import { ActivityForm } from './components/ActivityForm';
import { CategoryFilter } from './components/CategoryFilter';
import { DayNavigator } from './components/DayNavigator';
import type { Tab } from './types';

function App(): JSX.Element {
  const [appData, setAppData] = useState(load);

  const [selectedDate, setSelectedDate] = useState(getToday());
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [tab, setTab] = useState<Tab>('aktivitäten');
  const [formOpen, setFormOpen] = useState(false);

  const dayData = useDayData(appData, {
    selectedDate,
    selectedCategory,
    tab,
    onDateChange: setSelectedDate,
    onCategoryChange: setSelectedCategory,
    onTabChange: setTab,
  });

  const today = getToday();

  const handleToggleComplete = (activityId: string, completed: boolean) => {
    const newData = dayData.toggleComplete(activityId, completed);
    setAppData(newData);
    save(newData);
  };

  const handleDeleteActivity = (activityId: string) => {
    if (!window.confirm('Aktivität wirklich löschen?')) return;
    const newData = dayData.deleteActivity(activityId);
    setAppData(newData);
    save(newData);
  };

  const handleAddActivity = (activity: {
    id: string;
    name: string;
    description?: string;
    category: string;
    dailyTarget?: number;
    createdAt: number;
  }) => {
    const newData = {
      ...appData,
      activities: [...appData.activities, activity],
    };
    setAppData(newData);
    save(newData);
  };

  return (
    <div className="app">
      <header className="app-header">
        <div className="app-title">
          <span className="title-bar" />
          <h1>PulseBoard</h1>
        </div>
        <div className="app-tabs">
          <button
            className={`tab-btn${tab === 'aktivitäten' ? ' active' : ''}`}
            onClick={() => setTab('aktivitäten')}
          >
            Aktivitäten
          </button>
          <button
            className={`tab-btn${tab === 'dashboard' ? ' active' : ''}`}
            onClick={() => setTab('dashboard')}
          >
            Dashboard
          </button>
        </div>
      </header>

      <main className="app-main">
        {tab === 'aktivitäten' ? (
          <>
            <DayNavigator
              selectedDate={selectedDate}
              yesterday={dayData.yesterday}
              tomorrow={dayData.tomorrow}
              onNavigate={setSelectedDate}
              onToday={() => setSelectedDate(today)}
              onPrev={() => setSelectedDate(dayData.yesterday)}
              onNext={() => setSelectedDate(dayData.tomorrow)}
            />

            <div className="progress-bar-wrap">
              <div
                className="progress-bar"
                style={{ width: `${dayData.stats.percentage}%` }}
              />
            </div>

            <div className="stats-inline">
              <span>
                {dayData.stats.completed} von {dayData.activities.length}
              </span>
              <span>{dayData.stats.percentage}%</span>
            </div>

            <CategoryFilter
              categories={dayData.categories}
              selectedCategory={dayData.selectedCategory}
              onFilter={setSelectedCategory}
            />

            <ActivitiesPanel
              activities={dayData.activities}
              isFuture={dayData.isFuture}
              isToday={dayData.isToday}
              onToggleComplete={handleToggleComplete}
              onDelete={handleDeleteActivity}
            />

            <button
              className="fab"
              onClick={() => setFormOpen(true)}
              aria-label="Aktivität hinzufügen"
            >
              +
            </button>
          </>
        ) : (
          <Dashboard
            activities={dayData.activities}
            categoryStats={dayData.categoryStats}
          />
        )}
      </main>

      {formOpen && (
        <div className="modal-overlay" onClick={() => setFormOpen(false)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <ActivityForm
              categories={dayData.categories}
              existingNames={appData.activities.map((a) => a.name.toLowerCase())}
              onSubmit={handleAddActivity}
              onClose={() => setFormOpen(false)}
            />
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

import { afterEach } from 'vitest';
import { cleanup } from '@testing-library/react';
import * as matchers from '@testing-library/jest-dom/matchers';

expect.extend(matchers);

afterEach(() => {
  cleanup();
  localStorage.clear();
});

import { describe, it, expect } from 'vitest';
import {
  load,
  save,
  freshData,
  markComplete,
  addActivity,
  updateActivity,
  removeActivity,
  getIsComplete,
  getCompletionsForDate,
  isFutureDate,
  isToday,
  formatGermanDate,
  getToday,
  getYesterday,
  getTomorrow,
} from '../lib/storage';
import type { AppData } from '../types';

// Utility to set localStorage before loading
function setStored(data: AppData): void {
  localStorage.setItem('pulseboard:data:v1', JSON.stringify(data));
}

describe('load / save / freshData', () => {
  it('returns freshData when localStorage is empty', () => {
    const result = load();
    expect(result.version).toBe(1);
    expect(result.activities).toEqual([]);
    expect(result.completions).toEqual([]);
  });

  it('parses valid stored data', () => {
    const data: AppData = {
      version: 1,
      activities: [{
        id: 'a1',
        name: 'Sport',
        category: 'Gesundheit',
        createdAt: 1000,
      }],
      completions: [],
    };
    setStored(data);
    const result = load();
    expect(result.activities.length).toBe(1);
    expect(result.activities[0].name).toBe('Sport');
  });

  it('returns freshData on corrupt JSON', () => {
    localStorage.setItem('pulseboard:data:v1', 'not json {{{');
    const result = load();
    expect(result.version).toBe(1);
    expect(result.activities).toEqual([]);
  });

  it('returns freshData when data object is malformed', () => {
    setStored({} as AppData);
    const result = load();
    expect(result.version).toBe(1);
  });

  it('returns freshData when version is missing', () => {
    setStored({ activities: [], completions: [] } as unknown as AppData);
    const result = load();
    expect(result.version).toBe(1);
  });

  it('save / load roundtrip preserves data', () => {
    const data: AppData = {
      version: 1,
      activities: [{
        id: 'x1',
        name: 'Lesen',
        category: 'Bildung',
        createdAt: 5000,
      }],
      completions: [{ date: '2099-01-01', completions: { x1: true } }],
    };
    save(data);
    const loaded = load();
    expect(loaded.activities[0].name).toBe('Lesen');
    expect(loaded.completions[0].completions.x1).toBe(true);
  });
});

describe('markComplete', () => {
  it('marks an activity as complete', () => {
    const data: AppData = freshData();
    const withActivity = addActivity(data, {
      id: 'act1',
      name: 'Yoga',
      category: 'Gesundheit',
      createdAt: 0,
    });
    const result = markComplete(withActivity, '2025-06-15', 'act1', true);
    expect(getIsComplete(result, '2025-06-15', 'act1')).toBe(true);
  });

  it('unmarks an activity', () => {
    const withCompletion = addActivity(freshData(), {
      id: 'act2',
      name: 'Laufen',
      category: 'Gesundheit',
      createdAt: 0,
    });
    const marked = markComplete(withCompletion, '2025-07-20', 'act2', true);
    const unmarked = markComplete(marked, '2025-07-20', 'act2', false);
    expect(getIsComplete(unmarked, '2025-07-20', 'act2')).toBe(false);
  });

  it('does not affect other dates', () => {
    const data = addActivity(freshData(), { id: 'a', name: 'Test', category: 'X', createdAt: 0 });
    const d1 = markComplete(data, '2025-01-01', 'a', true);
    const d2 = markComplete(data, '2025-02-02', 'a', false);
    expect(getIsComplete(d1, '2025-01-01', 'a')).toBe(true);
    expect(getIsComplete(d2, '2025-02-02', 'a')).toBe(false);
  });
});

describe('add / update / remove activity', () => {
  it('adds an activity', () => {
    const data = addActivity(freshData(), {
      id: 'n1',
      name: 'Kochen',
      category: 'Persönlich',
      createdAt: 100,
    });
    expect(data.activities.length).toBe(1);
    expect(data.activities[0].name).toBe('Kochen');
  });

  it('updates an activity', () => {
    const data = addActivity(freshData(), {
      id: 'n2',
      name: 'Kaffee',
      category: 'Gesundheit',
      createdAt: 0,
    });
    const updated = updateActivity(data, 'n2', { name: 'Kaffee groß' });
    expect(updated.activities[0].name).toBe('Kaffee groß');
    expect(updated.activities[0].category).toBe('Gesundheit'); // unchanged
  });

  it('removes an activity and cleans completions', () => {
    const data = addActivity(freshData(), {
      id: 'n3',
      name: 'Wasser',
      category: 'Gesundheit',
      createdAt: 0,
    });
    const completed = markComplete(data, '2025-03-01', 'n3', true);
    const removed = removeActivity(completed, 'n3');
    expect(removed.activities.length).toBe(0);
    expect(removed.completions.length).toBe(0);
  });
});

describe('date utilities', () => {
  it('formatGermanDate returns DE formatted string', () => {
    expect(formatGermanDate('2026-09-25')).toBe('Fr., 25. September 2026');
  });

  it('getYesterday returns correct ISO date', () => {
    expect(getYesterday('2026-09-26')).toBe('2026-09-25');
  });

  it('getTomorrow returns correct ISO date', () => {
    expect(getTomorrow('2026-09-25')).toBe('2026-09-26');
  });

  it('getTomorrow crosses month boundary', () => {
    expect(getTomorrow('2026-02-28')).toBe('2026-03-01');
  });

  it('getYesterday crosses year boundary', () => {
    expect(getYesterday('2027-01-01')).toBe('2026-12-31');
  });
});

import { describe, it, expect, vi } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useDayData } from '../hooks/useDayData';
import { freshData, addActivity, markComplete } from '../lib/storage';
import type { AppData } from '../types';

function makeDate(dateStr: string) {
  return {
    selectedDate: dateStr,
    selectedCategory: null,
    tab: 'aktivitäten' as const,
    onDateChange: vi.fn(),
    onCategoryChange: vi.fn(),
    onTabChange: vi.fn(),
  };
}

function makeHook(data: AppData) {
  return renderHook(() =>
    useDayData(data, makeDate('2025-06-15'))
  );
}

describe('useDayData - activities', () => {
  it('returns empty activities when none exist', () => {
    const { result } = makeHook(freshData());
    expect(result.current.activities).toEqual([]);
  });

  it('returns activities with completion status', () => {
    const data = addActivity(freshData(), {
      id: 'x',
      name: 'Spazieren',
      category: 'Freizeit',
      createdAt: 0,
    });
    const marked = markComplete(data, '2025-06-15', 'x', true);
    const { result } = makeHook(marked);
    expect(result.current.activities.length).toBe(1);
    expect(result.current.activities[0].isComplete).toBe(true);
  });

  it('unmarked activities show isComplete false', () => {
    const data = addActivity(freshData(), {
      id: 'y',
      name: 'Lesen',
      category: 'Bildung',
      createdAt: 0,
    });
    const { result } = makeHook(data);
    expect(result.current.activities[0].isComplete).toBe(false);
  });
});

describe('useDayData - completion toggle', () => {
  it('toggleComplete returns updated AppData', () => {
    const data = addActivity(freshData(), {
      id: 't1',
      name: 'Meditation',
      category: 'Persönlich',
      createdAt: 0,
    });
    const { result } = makeHook(data);
    const updated = act(() => result.current.toggleComplete('t1', true));
    expect(updated.version).toBe(1);
    const { result: r2 } = makeHook(updated);
    expect(
      r2.current.activities.find((a) => a.activity.id === 't1')?.isComplete
    ).toBe(true);
  });

  it('toggleComplete toggles true → false', () => {
    const data = addActivity(freshData(), {
      id: 't2',
      name: 'Hausaufgaben',
      category: 'Bildung',
      createdAt: 0,
    });
    const marked = markComplete(data, '2025-06-15', 't2', true);
    const { result } = makeHook(marked);
    const unmarked = act(() => result.current.toggleComplete('t2', false));
    const { result: r2 } = makeHook(unmarked);
    expect(
      r2.current.activities.find((a) => a.activity.id === 't2')?.isComplete
    ).toBe(false);
  });
});

describe('useDayData - delete', () => {
  it('deleteActivity removes the activity from list', () => {
    const data = addActivity(freshData(), {
      id: 'del1',
      name: 'Aufräumen',
      category: 'Haus',
      createdAt: 0,
    });
    const { result } = makeHook(data);
    const updated = act(() => result.current.deleteActivity('del1'));
    expect(updated.activities.length).toBe(0);
  });
});

describe('useDayData - stats', () => {
  it('computes correct stats', () => {
    const data = addActivity(freshData(), { id: 's1', name: 'A', category: 'K', createdAt: 0 });
    const data2 = addActivity(data, { id: 's2', name: 'B', category: 'K', createdAt: 0 });
    const data3 = addActivity(data2, { id: 's3', name: 'C', category: 'K', createdAt: 0 });
    const done = markComplete(data3, '2025-06-15', 's1', true);
    const done2 = markComplete(done, '2025-06-15', 's2', true);
    const { result } = makeHook(done2);
    expect(result.current.stats.completed).toBe(2);
    expect(result.current.stats.open).toBe(1);
    expect(result.current.stats.percentage).toBe(67);
  });
});

describe('useDayData - category stats', () => {
  it('computes category breakdown', () => {
    const data = addActivity(freshData(), { id: 'c1', name: 'A', category: 'Sport', createdAt: 0 });
    const data2 = addActivity(data, { id: 'c2', name: 'B', category: 'Sport', createdAt: 0 });
    const data3 = addActivity(data2, { id: 'c3', name: 'C', category: 'Arbeit', createdAt: 0 });
    const done = markComplete(data3, '2025-06-15', 'c1', true);
    const { result } = makeHook(done);
    expect(result.current.categoryStats.length).toBe(2);
  });
});

describe('useDayData - future / today flags', () => {
  it('isToday is true when date equals today', () => {
    const { result } = makeHook(freshData());
    expect(result.current.isToday).toBe(true);
  });
});

describe('useDayData - completion isolation', () => {
  it('a different date has different completion state', () => {
    const data = addActivity(freshData(), { id: 'iso1', name: 'Test', category: 'X', createdAt: 0 });
    const withCompletion = markComplete(data, '2024-12-31', 'iso1', true);
    const hook = makeHook(withCompletion);
    expect(hook.result.current.activities[0].isComplete).toBe(false);
  });
});

import type { Activity } from '../types';
import type { AppData } from '../types';
import { generateId } from '../lib/generateId';

export interface UseActivitiesInput {
  activities: Activity[];
  onUpdate: (data: AppData) => void;
}

export function useActivities({ activities, onUpdate }: UseActivitiesInput) {
  const addActivity = (activity: Omit<Activity, 'id' | 'createdAt'>): void => {
    const newActivity: Activity = {
      ...activity,
      id: generateId(),
      createdAt: Date.now(),
    };
    onUpdate({
      version: 1,
      activities: [...activities, newActivity],
      completions: [],
    });
  };

  const updateActivity = (id: string, updates: Partial<Activity>): void => {
    onUpdate({
      version: 1,
      activities: activities.map((a) =>
        a.id === id ? { ...a, ...updates } : a
      ),
      completions: [],
    });
  };

  const deleteActivity = (id: string): void => {
    onUpdate({
      version: 1,
      activities: activities.filter((a) => a.id !== id),
      completions: [],
    });
  };

  return { addActivity, updateActivity, deleteActivity };
}

import { describe, it, expect, vi } from 'vitest';
import { useActivities } from '../hooks/useActivities';
import type { Activity } from '../types';

describe('useActivities', () => {
  function createHook(activities: Activity[] = []) {
    const onUpdate = vi.fn();
    const hook = useActivities({ activities, onUpdate });
    return { hook, onUpdate, activities };
  }

  it('adds an activity', () => {
    const { hook, onUpdate, activities } = createHook();
    hook.addActivity({ name: 'Sport', category: 'Gesundheit' });
    expect(onUpdate).toHaveBeenCalledTimes(1);
    const updatedData = (onUpdate.mock.calls[0] as any)[0];
    expect(updatedData.activities.length).toBe(1);
    expect(updatedData.activities[0].name).toBe('Sport');
    expect(typeof updatedData.activities[0].id).toBe('string');
    expect(updatedData.activities[0].createdAt).toBeGreaterThan(0);
  });

  it('updates an activity name', () => {
    const existing: Activity[] = [
      { id: 'a1', name: 'Kaffee', category: 'Gesundheit', createdAt: 0 },
    ];
    const { hook } = createHook(existing);
    hook.updateActivity('a1', { name: 'Kaffee groß' });
    expect(onUpdate).toHaveBeenCalledTimes(1);
    const updatedData = (onUpdate.mock.calls[0] as any)[0];
    expect(updatedData.activities[0].name).toBe('Kaffee groß');
    expect(updatedData.activities[0].category).toBe('Gesundheit'); // preserved
  });

  it('deletes an activity', () => {
    const existing: Activity[] = [
      { id: 'del1', name: 'Aufräumen', category: 'Haus', createdAt: 0 },
      { id: 'del2', name: 'Waschen', category: 'Haus', createdAt: 0 },
    ];
    const { hook } = createHook(existing);
    hook.deleteActivity('del1');
    expect(onUpdate).toHaveBeenCalledTimes(1);
    const updatedData = (onUpdate.mock.calls[0] as any)[0];
    expect(updatedData.activities.length).toBe(1);
    expect(updatedData.activities[0].id).toBe('del2');
  });

  it('addActivity generates unique IDs', () => {
    const { hook } = createHook();
    hook.addActivity({ name: 'A', category: 'X' });
    hook.addActivity({ name: 'B', category: 'X' });
    const updatedData = (onUpdate.mock.calls[1] as any)[0];
    expect(updatedData.activities.length).toBe(2);
    expect(updatedData.activities[0].id).not.toBe(updatedData.activities[1].id);
  });
});

