import { STORAGE_KEY, CURRENT_VERSION, CATEGORIES } from '../constants';
import type { AppData, CompletionRecord, Activity } from '../types';

let pendingWrite: Promise<void> | null = null;

function deserialize(raw: string | null): AppData | null {
  if (raw === null) return null;
  try {
    const data = JSON.parse(raw) as AppData;
    if (typeof data !== 'object' || data === null) return null;
    if (typeof data.version !== 'number' || data.version < 1) return null;
    if (!Array.isArray(data.activities)) return null;
    if (!Array.isArray(data.completions)) return null;
    // Validate activities
    for (const a of data.activities) {
      if (typeof a.id !== 'string') return null;
      if (typeof a.name !== 'string' || a.name.length === 0) return null;
    }
    // Validate completions
    for (const c of data.completions) {
      if (typeof c.date !== 'string') return null;
      if (typeof c.completions !== 'object' || c.completions === null) return null;
    }
    return data;
  } catch {
    return null;
  }
}

export function load(): AppData {
  const raw = localStorage.getItem(STORAGE_KEY);
  const parsed = deserialize(raw);
  if (parsed !== null) return parsed;
  // Return fresh default on failure/corruption
  console.warn('PulseBoard: konnte Daten nicht laden, starte mit leerer Datei.');
  return freshData();
}

export function save(data: AppData): void {
  if (pendingWrite) return; // prevent race writes
  pendingWrite = Promise.resolve().then(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    pendingWrite = null;
  });
}

export function getAllCategories(data: AppData): string[] {
  const categories = new Set<string>();
  for (const activity of data.activities) {
    if (activity.category.trim()) categories.add(activity.category.trim());
  }
  const fallback = CATEGORIES.filter((c) => !data.activities.some((a) => a.category === c));
  return [...categories, ...fallback];
}

export function getToday(): string {
  const now = new Date();
  // Convert to UTC midnight to avoid timezone issues
  const utcDate = new Date(
    Date.UTC(now.getFullYear(), now.getMonth(), now.getDate())
  );
  return utcDate.toISOString().slice(0, 10);
}

export function getYesterday(date: string): string {
  return shiftDate(date, -1);
}

export function getTomorrow(date: string): string {
  return shiftDate(date, 1);
}

function shiftDate(date: string, days: number): string {
  const [year, month, day] = date.split('-').map(Number);
  // Use UTC to avoid timezone offset issues
  const d = new Date(Date.UTC(year, month - 1, day + days));
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${dd}`;
}

export function formatGermanDate(iso: string): string {
  const [year, month, day] = iso.split('-').map(Number);
  const d = new Date(year, month - 1, day);
  const options: Intl.DateTimeFormatOptions = {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
    weekday: 'short',
  };
  return d.toLocaleDateString('de-DE', options);
}

export function freshData(): AppData {
  return {
    version: CURRENT_VERSION,
    activities: [],
    completions: [],
  };
}

export function markComplete(data: AppData, date: string, activityId: string, completed: boolean): AppData {
  const existing = data.completions.find((c) => c.date === date);
  let completions: CompletionRecord[];
  if (existing) {
    completions = data.completions.map((c) =>
      c.date === date
        ? { ...c, completions: { ...c.completions, [activityId]: completed } }
        : c
    );
  } else {
    completions = [
      ...data.completions,
      { date, completions: { [activityId]: completed } },
    ];
  }
  return { ...data, completions };
}

export function addActivity(data: AppData, activity: Activity): AppData {
  return { ...data, activities: [...data.activities, activity] };
}

export function updateActivity(data: AppData, activityId: string, updates: Partial<Activity>): AppData {
  return {
    ...data,
    activities: data.activities.map((a) =>
      a.id === activityId ? { ...a, ...updates } : a
    ),
  };
}

export function removeActivity(data: AppData, activityId: string): AppData {
  return {
    ...data,
    activities: data.activities.filter((a) => a.id !== activityId),
    completions: data.completions.map((c) => {
      const newCompletions = { ...c.completions };
      delete newCompletions[activityId];
      return { ...c, completions: newCompletions };
    }).filter((c) => Object.keys(c.completions).length > 0),
  };
}

export function getCompletionsForDate(data: AppData, date: string): CompletionRecord | undefined {
  return data.completions.find((c) => c.date === date);
}

export function getIsComplete(data: AppData, date: string, activityId: string): boolean {
  const record = data.completions.find((c) => c.date === date);
  return record?.completions[activityId] === true;
}

export function isFutureDate(date: string): boolean {
  return date > getToday();
}

export function isToday(date: string): boolean {
  return date === getToday();
}

import { describe, it, expect } from 'vitest';
import {
  load,
  save,
  freshData,
  markComplete,
  addActivity,
  updateActivity,
  removeActivity,
  getIsComplete,
  isFutureDate,
  formatGermanDate,
  getToday,
  getYesterday,
  getTomorrow,
} from '../lib/storage';
import type { AppData } from '../types';

// Utility to set localStorage before loading
function setStored(data: AppData): void {
  localStorage.setItem('pulseboard:data:v1', JSON.stringify(data));
}

describe('load / save / freshData', () => {
  it('returns freshData when localStorage is empty', () => {
    const result = load();
    expect(result.version).toBe(1);
    expect(result.activities).toEqual([]);
    expect(result.completions).toEqual([]);
  });

  it('parses valid stored data', () => {
    const data: AppData = {
      version: 1,
      activities: [{
        id: 'a1',
        name: 'Sport',
        category: 'Gesundheit',
        createdAt: 1000,
      }],
      completions: [],
    };
    setStored(data);
    const result = load();
    expect(result.activities.length).toBe(1);
    expect(result.activities[0].name).toBe('Sport');
  });

  it('returns freshData on corrupt JSON', () => {
    localStorage.setItem('pulseboard:data:v1', 'not json {{{');
    const result = load();
    expect(result.version).toBe(1);
    expect(result.activities).toEqual([]);
  });

  it('returns freshData when data object is malformed', () => {
    setStored({} as AppData);
    const result = load();
    expect(result.version).toBe(1);
  });

  it('returns freshData when version is missing', () => {
    setStored({ activities: [], completions: [] } as unknown as AppData);
    const result = load();
    expect(result.version).toBe(1);
  });

  it('save / load roundtrip preserves data', () => {
    const data: AppData = {
      version: 1,
      activities: [{
        id: 'x1',
        name: 'Lesen',
        category: 'Bildung',
        createdAt: 5000,
      }],
      completions: [{ date: '2099-01-01', completions: { x1: true } }],
    };
    save(data);
    const loaded = load();
    expect(loaded.activities[0].name).toBe('Lesen');
    expect(loaded.completions[0].completions.x1).toBe(true);
  });
});

describe('markComplete', () => {
  it('marks an activity as complete and creates a record', () => {
    const data = addActivity(freshData(), {
      id: 'act1',
      name: 'Yoga',
      category: 'Gesundheit',
      createdAt: 0,
    });
    const result = markComplete(data, '2025-06-15', 'act1', true);
    expect(getIsComplete(result, '2025-06-15', 'act1')).toBe(true);
  });

  it('unmarks an activity', () => {
    const withCompletion = addActivity(freshData(), {
      id: 'act2',
      name: 'Laufen',
      category: 'Gesundheit',
      createdAt: 0,
    });
    const marked = markComplete(withCompletion, '2025-07-20', 'act2', true);
    const unmarked = markComplete(marked, '2025-07-20', 'act2', false);
    expect(getIsComplete(unmarked, '2025-07-20', 'act2')).toBe(false);
  });

  it('does not affect other dates', () => {
    const data = addActivity(freshData(), { id: 'a', name: 'Test', category: 'X', createdAt: 0 });
    const d1 = markComplete(data, '2025-01-01', 'a', true);
    const d2 = markComplete(data, '2025-02-02', 'a', false);
    expect(getIsComplete(d1, '2025-01-01', 'a')).toBe(true);
    expect(getIsComplete(d2, '2025-02-02', 'a')).toBe(false);
  });
});

describe('add / update / remove activity', () => {
  it('adds an activity', () => {
    const data = addActivity(freshData(), {
      id: 'n1',
      name: 'Kochen',
      category: 'Persönlich',
      createdAt: 100,
    });
    expect(data.activities.length).toBe(1);
    expect(data.activities[0].name).toBe('Kochen');
  });

  it('updates an activity', () => {
    const data = addActivity(freshData(), {
      id: 'n2',
      name: 'Kaffee',
      category: 'Gesundheit',
      createdAt: 0,
    });
    const updated = updateActivity(data, 'n2', { name: 'Kaffee groß' });
    expect(updated.activities[0].name).toBe('Kaffee groß');
    expect(updated.activities[0].category).toBe('Gesundheit'); // unchanged
  });

  it('removes an activity and cleans completions', () => {
    const data = addActivity(freshData(), {
      id: 'n3',
      name: 'Wasser',
      category: 'Gesundheit',
      createdAt: 0,
    });
    const completed = markComplete(data, '2025-03-01', 'n3', true);
    const removed = removeActivity(completed, 'n3');
    expect(removed.activities.length).toBe(0);
    expect(removed.completions.length).toBe(0);
  });
});

describe('date utilities', () => {
  it('formatGermanDate returns DE formatted string', () => {
    expect(formatGermanDate('2026-09-25')).toBe('Fr., 25. September 2026');
  });

  it('getYesterday returns correct ISO date', () => {
    expect(getYesterday('2026-09-26')).toBe('2026-09-25');
  });

  it('getTomorrow returns correct ISO date', () => {
    expect(getTomorrow('2026-09-25')).toBe('2026-09-26');
  });

  it('getTomorrow crosses month boundary', () => {
    expect(getTomorrow('2026-02-28')).toBe('2026-03-01');
  });

  it('getYesterday crosses year boundary', () => {
    expect(getYesterday('2027-01-01')).toBe('2026-12-31');
  });

  it('isFutureDate returns false for dates before today', () => {
    const today = getToday();
    expect(isFutureDate(today)).toBe(false);
    expect(isFutureDate(getYesterday(today))).toBe(false);
  });

  it('isFutureDate returns true for dates after today', () => {
    const today = getToday();
    expect(isFutureDate(getTomorrow(today))).toBe(true);
  });
});

import { describe, it, expect, vi } from 'vitest';
import { useActivities } from '../hooks/useActivities';
import type { Activity } from '../types';

describe('useActivities', () => {
  function createHook(activities: Activity[] = []) {
    const onUpdate = vi.fn();
    const hook = useActivities({ activities, onUpdate });
    return { hook, onUpdate, activities };
  }

  it('adds an activity', () => {
    const { hook, onUpdate } = createHook();
    hook.addActivity({ name: 'Sport', category: 'Gesundheit' });
    expect(onUpdate).toHaveBeenCalledTimes(1);
    const updatedData = (onUpdate.mock.calls[0] as any)[0];
    expect(updatedData.activities.length).toBe(1);
    expect(updatedData.activities[0].name).toBe('Sport');
    expect(typeof updatedData.activities[0].id).toBe('string');
    expect(updatedData.activities[0].createdAt).toBeGreaterThan(0);
  });

  it('updates an activity name', () => {
    const existing: Activity[] = [
      { id: 'a1', name: 'Kaffee', category: 'Gesundheit', createdAt: 0 },
    ];
    const { hook, onUpdate } = createHook(existing);
    hook.updateActivity('a1', { name: 'Kaffee groß' });
    expect(onUpdate).toHaveBeenCalledTimes(1);
    const updatedData = (onUpdate.mock.calls[0] as any)[0];
    expect(updatedData.activities[0].name).toBe('Kaffee groß');
    expect(updatedData.activities[0].category).toBe('Gesundheit'); // preserved
  });

  it('deletes an activity', () => {
    const existing: Activity[] = [
      { id: 'del1', name: 'Aufräumen', category: 'Haus', createdAt: 0 },
      { id: 'del2', name: 'Waschen', category: 'Haus', createdAt: 0 },
    ];
    const { hook, onUpdate } = createHook(existing);
    hook.deleteActivity('del1');
    expect(onUpdate).toHaveBeenCalledTimes(1);
    const updatedData = (onUpdate.mock.calls[0] as any)[0];
    expect(updatedData.activities.length).toBe(1);
    expect(updatedData.activities[0].id).toBe('del2');
  });

  it('addActivity generates unique IDs', () => {
    const { hook, onUpdate } = createHook();
    hook.addActivity({ name: 'A', category: 'X' });
    hook.addActivity({ name: 'B', category: 'X' });
    const updatedData = (onUpdate.mock.calls[1] as any)[0];
    expect(updatedData.activities.length).toBe(2);
    expect(updatedData.activities[0].id).not.toBe(updatedData.activities[1].id);
  });
});

import { describe, it, expect, vi } from 'vitest';
import { renderHook } from '@testing-library/react';
import { useDayData } from '../hooks/useDayData';
import { freshData, addActivity, markComplete, getToday } from '../lib/storage';
import type { AppData } from '../types';

function makeDate(dateStr: string) {
  return {
    selectedDate: dateStr,
    selectedCategory: null,
    tab: 'aktivitäten' as const,
    onDateChange: vi.fn(),
    onCategoryChange: vi.fn(),
    onTabChange: vi.fn(),
  };
}

function makeHook(data: AppData, dateStr: string = '2025-06-15') {
  return renderHook(() =>
    useDayData(data, makeDate(dateStr))
  );
}

// Fix: isToday uses getToday() internally, so we must mock it
describe('useDayData - isToday', () => {
  it('isToday is true when selectedDate equals today', () => {
    const today = getToday();
    const hook = renderHook(() =>
      useDayData(freshData(), makeDate(today))
    );
    expect(hook.result.current.isToday).toBe(true);
  });

  it('isToday is false for arbitrary dates', () => {
    const hook = makeHook(freshData(), '2025-01-01');
    expect(hook.result.current.isToday).toBe(false);
  });
});

describe('useDayData - activities', () => {
  it('returns empty activities when none exist', () => {
    const { result } = makeHook(freshData());
    expect(result.current.activities).toEqual([]);
  });

  it('returns activities with completion status', () => {
    const data = addActivity(freshData(), {
      id: 'x',
      name: 'Spazieren',
      category: 'Freizeit',
      createdAt: 0,
    });
    const marked = markComplete(data, '2025-06-15', 'x', true);
    const { result } = makeHook(marked, '2025-06-15');
    expect(result.current.activities.length).toBe(1);
    expect(result.current.activities[0].isComplete).toBe(true);
  });

  it('unmarked activities show isComplete false', () => {
    const data = addActivity(freshData(), {
      id: 'y',
      name: 'Lesen',
      category: 'Bildung',
      createdAt: 0,
    });
    const { result } = makeHook(data);
    expect(result.current.activities[0].isComplete).toBe(false);
  });
});

describe('useDayData - completion toggle', () => {
  it('toggleComplete returns updated AppData', () => {
    const data = addActivity(freshData(), {
      id: 't1',
      name: 'Meditation',
      category: 'Persönlich',
      createdAt: 0,
    });
    const { result } = makeHook(data);
    const updated = result.current.toggleComplete('t1', true);
    expect(updated.version).toBe(1);
    const { result: r2 } = makeHook(updated, '2025-06-15');
    expect(
      r2.current.activities.find((a) => a.activity.id === 't1')?.isComplete
    ).toBe(true);
  });

  it('toggleComplete toggles true → false', () => {
    const data = addActivity(freshData(), {
      id: 't2',
      name: 'Hausaufgaben',
      category: 'Bildung',
      createdAt: 0,
    });
    const marked = markComplete(data, '2025-06-15', 't2', true);
    const { result } = makeHook(marked, '2025-06-15');
    const unmarked = result.current.toggleComplete('t2', false);
    const { result: r2 } = makeHook(unmarked, '2025-06-15');
    expect(
      r2.current.activities.find((a) => a.activity.id === 't2')?.isComplete
    ).toBe(false);
  });
});

describe('useDayData - delete', () => {
  it('deleteActivity removes the activity from list', () => {
    const data = addActivity(freshData(), {
      id: 'del1',
